data.mutation:
mutation(
  $payload: [AssetUpdatePayloadInput!]!,
){
  updateAsset(payload:$payload){
    id
    currentHours
    lifetimeHours
    currentCycles
    lifetimeCycles
  }
}

data.transform:
/*
INPUT - 
raw PRM record

OUTPUT - 
1 per PRM record


(
$prm := productionRunMaintenance.edges.node.(
    {
    "id":id,
    "maintenanceCycles" : maintenanceCycles,
    "maintenanceHours" : maintenanceHours,
    "assetId" : assetId,
    "productionRunId" : productionRunId
    }
  );

$groupby($.assetId)

)
*/

$reduce($.productionRunMaintenance.edges.node,function($acc, $curr) {
    $append($filter($acc, function($item) { $item.assetId != $curr.assetId }),
      [{
          "assetId": $curr.assetId,
          "maintenanceCycles": $sum($append($filter($acc, function($item) { $item.assetId = $curr.assetId }).maintenanceCycles,$curr.maintenanceCycles)),
          "maintenanceHours": $sum($append($filter($acc, function($item) { $item.assetId = $curr.assetId }).maintenanceHours,$curr.maintenanceHours)),
          "prmId": $curr.id
        }])},
  []
)









 /* $groupby($.assetId) */

{
  "SUCCESS": true,
  "MESSAGE": "Assets updated successfull with the following values: "
    & $.updateAsset
}

data.query:
query Query($wherePRM: ProductionRunMaintenanceWhereInput) {
  productionRunMaintenance : productionRunMaintenance(where: $wherePRM) {
    edges {
      node {
        id
        maintenanceCycles
        maintenanceHours
        assetId
        productionRunId
        productionRun{
          id
          startAt
          endAt
        }
      }
    }
  }
}

data.transform:
/*
$inner
USE inner join (JSONATA) to combine the 
INPUT -
1 per asset id, per ph record
{
  "id": "clwaxnjhy1b6u015dgczs8d3e",
  "units": 1,
  "hours": 0.39445305555555554,
  "cycles": 1
}
OUTPUT - 
update payload for giving new asset hours


{
    "payloads": $map($, function($v) {
        {
            "payload": {
                "update": {"maintenanceHours" : $coalesce([maintHours,0])},
                "where": {"id": $v.id}
            }
        }
    })
}



{"payload": 
    {
      "update": {"maintenanceHours" : $coalesce([maintHours,0])},
      "where": {"id": id}
    }

}

*/

{
    "payload": $map($, function($v) {
        {
            "update": {
              "currentHours" : $coalesce([maintenanceHours,0]),
              "currentCycles" : $coalesce([maintenanceCycles,0])},
            "where": {"id": $v.assetId}
        }
    })
}

